use vstd::prelude::*;
use vstd::vec::*;

type Matrix<T> = Vec<Vec<T>>;

verus! {

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (matrix: Matrix<i8>)
    requires
        shape.len() == 2,
        shape[0] > 0 && shape[1] > 0,
        a.len() > 0,
        a.len() == shape[0] as usize || a.len() == shape[1] as usize,
    ensures
        matrix.len() == shape[0] as usize,
        forall |i: int| 0 <= i < matrix.len() ==> matrix[i].len() == shape[1] as usize,
        // If array length matches rows, each column in a row has the same value
        (a.len() == shape[0] as usize) ==> 
            (forall |i: int, j: int| 0 <= i < matrix.len() && 0 <= j < matrix[i].len() ==> 
                matrix[i][j] == a[i]),
        // If array length matches columns, each row is a copy of the array
        (a.len() == shape[1] as usize) ==> 
            (forall |i: int| 0 <= i < matrix.len() ==> matrix[i] == a),
{
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Get the length of the input array
    let a_len = a.len();
    
    // Check which dimension matches the array length
    if a_len == r {
        // Array is a column vector - broadcast across columns
        let mut matrix = Vec::with_capacity(r);
        
        let mut i: usize = 0;
        while i < r
            invariant
                0 <= i <= r,
                matrix.len() == i,
                forall |k: int| 0 <= k < i ==> matrix[k].len() == c,
                forall |k: int, j: int| 0 <= k < i && 0 <= j < c ==> matrix[k][j] == a[k],
        {
            let row = vec![a[i]; c];
            proof {
                // Prove that the created row has the correct properties
                let row_spec = row;
                assert(row_spec.len() == c);
                assert(forall |j: int| 0 <= j < c ==> row_spec[j] == a[i]);
            }
            matrix.push(row);
            i += 1;
        }
        
        matrix
    } else if a_len == c {
        // Array is a row vector - broadcast across rows
        let mut matrix = Vec::with_capacity(r);
        
        let mut i: usize = 0;
        while i < r
            invariant
                0 <= i <= r,
                matrix.len() == i,
                forall |k: int| 0 <= k < i ==> matrix[k] == a,
        {
            matrix.push(a.clone());
            i += 1;
        }
        
        matrix
    } else {
        // According to the problem statement, this shouldn't happen
        // as at least one dimension must match, but we handle it defensively
        panic!("Array length must match either R or C");
    }
}

} // verus!